"""US-765: the server has somewhere to put EDR samples.

The shape of both tables lives in ``src/common/edr`` (US-764). Nothing below
restates a column: the model is compared against the generator's output, and the
migration's SQL is compared against the generator's call.
"""

from __future__ import annotations

import re
from types import SimpleNamespace
from typing import Any

import pytest
from sqlalchemy import create_engine, func, select
from sqlalchemy.dialects import mysql, sqlite
from sqlalchemy.dialects.mysql import insert as mysql_insert
from sqlalchemy.dialects.sqlite import insert as sqlite_insert
from sqlalchemy.orm import Session
from sqlalchemy.schema import CreateTable

from scripts.apply_server_migrations import MigrationError
from src.common.edr.server_ddl import (
    DEVICE_TS_KEY_COLUMNS,
    PRIMARY_KEY_COLUMNS,
    buildRawTableDdl,
)
